        if(region!=null&&!canvas.Get("_material_direction_set").AsBool()&&from.DistanceSquaredTo(to)>1){var template=_documents.live_material_for_id(document,canvas.Get("_material_template_id").AsString());if(template!=null&&template.Get("material").AsGodotObject().Get("alignment").AsString()=="stroke"){var inverse=_documents.world_transform(document,item).AffineInverse();float angle=-((inverse*to)-(inverse*from)).Angle();region.Set("mapping",new Transform2D(angle,-(inverse*canvas.Get("_material_stroke_anchor").AsVector2()).Rotated(angle)));}canvas.Set("_material_direction_set",true);}
        var image=canvas.Get("_paint_image").As<Image>();if(image==null||item==null)return;var ink=canvas.Get("_stroke_ink").As<Image>();double brushSize=canvas.Get("brush_size").AsDouble(),hardness=canvas.Get("hardness").AsDouble();var world=_documents.world_transform(document,item);var inverseWorld=world.AffineInverse();var ratio=(Vector2)image.GetSize()/item.Get("dimensions").AsVector2();bool erase=canvas.Get("tool").AsString()=="eraser"||canvas.Get("_erase_modifier").AsBool();
