    public void upload_paint(Control canvas){var image=canvas.Get("_paint_image").As<Image>();image.SetData(image.GetWidth(),image.GetHeight(),false,Image.Format.Rgba8,canvas.Get("_paint_data").AsByteArray());update_paint_texture(canvas);canvas.QueueRedraw();}
    public void replace_paint_texture(Control canvas){var region=canvas.Get("_material_region").AsGodotObject();var image=canvas.Get("_paint_image").As<Image>();if(region!=null)region.Set("coverage",ImageTexture.CreateFromImage(image));else canvas.Get("_paint_layer").AsGodotObject().Set("texture",ImageTexture.CreateFromImage(image));}
