        var region=canvas.Get("_material_region").AsGodotObject();var stamps=canvas.Get("_material_stamps").AsGodotObject();if(stamps!=null&&region!=null)_stampOperations.upload((RefCounted)stamps,(Resource)region);var item=canvas.Get("_paint_layer").AsGodotObject();var target=region??item;string property=region!=null?"coverage":"texture";var image=canvas.Get("_paint_image").As<Image>();if(target.Get(property).AsGodotObject() is ImageTexture texture)texture.Update(image);else target.Set(property,ImageTexture.CreateFromImage(image));var repair=canvas.Get("repair_tool").AsGodotObject();var workspace=repair?.Get("workspace").AsGodotObject();if(GodotObject.IsInstanceValid(workspace))workspace!.Get("renderer").AsGodotObject().Call("invalidate_layer",item.Get("id"));
